#include <stdio.h>
#include <stdlib.h>

#define HASH_SIZE 100

// Doubly Linked List Node
typedef struct Node {
    int key;
    int value;
    struct Node *prev;
    struct Node *next;
} Node;

// Hash Map Entry
typedef struct HashEntry {
    int key;
    Node *node;
    struct HashEntry *next;
} HashEntry;

typedef struct {
    int capacity;
    int size;
    Node *head;
    Node *tail;
    HashEntry *hash[HASH_SIZE];
} LRUCache;


// Hash function
int hashFunction(int key) {
    return abs(key) % HASH_SIZE;
}


// Find node in Hash Map
Node* findNode(LRUCache *cache, int key) {
    int index = hashFunction(key);
    HashEntry *current = cache->hash[index];

    while (current != NULL) {
        if (current->key == key)
            return current->node;

        current = current->next;
    }

    return NULL;
}


// Insert into Hash Map
void hashInsert(LRUCache *cache, int key, Node *node) {
    int index = hashFunction(key);

    HashEntry *entry = malloc(sizeof(HashEntry));

    entry->key = key;
    entry->node = node;
    entry->next = cache->hash[index];

    cache->hash[index] = entry;
}


// Delete from Hash Map
void hashDelete(LRUCache *cache, int key) {
    int index = hashFunction(key);

    HashEntry *current = cache->hash[index];
    HashEntry *prev = NULL;

    while (current != NULL) {
        if (current->key == key) {

            if (prev == NULL)
                cache->hash[index] = current->next;
            else
                prev->next = current->next;

            free(current);
            return;
        }

        prev = current;
        current = current->next;
    }
}


// Remove node from linked list
void removeNode(LRUCache *cache, Node *node) {
    node->prev->next = node->next;
    node->next->prev = node->prev;
}


// Add node after head
void addToFront(LRUCache *cache, Node *node) {
    node->next = cache->head->next;
    node->prev = cache->head;

    cache->head->next->prev = node;
    cache->head->next = node;
}


// Create LRU Cache
LRUCache* createCache(int capacity) {

    LRUCache *cache = malloc(sizeof(LRUCache));

    cache->capacity = capacity;
    cache->size = 0;

    // Dummy head and tail
    cache->head = malloc(sizeof(Node));
    cache->tail = malloc(sizeof(Node));

    cache->head->next = cache->tail;
    cache->tail->prev = cache->head;

    cache->head->prev = NULL;
    cache->tail->next = NULL;

    for (int i = 0; i < HASH_SIZE; i++)
        cache->hash[i] = NULL;

    return cache;
}


// Get value
int get(LRUCache *cache, int key) {

    Node *node = findNode(cache, key);

    if (node == NULL)
        return -1;

    // Move node to front
    removeNode(cache, node);
    addToFront(cache, node);

    return node->value;
}


// Put key-value pair
void put(LRUCache *cache, int key, int value) {

    Node *node = findNode(cache, key);

    // Key already exists
    if (node != NULL) {

        node->value = value;

        removeNode(cache, node);
        addToFront(cache, node);

        return;
    }

    // Create new node
    node = malloc(sizeof(Node));

    node->key = key;
    node->value = value;

    addToFront(cache, node);
    hashInsert(cache, key, node);

    cache->size++;

    // Remove LRU node if capacity exceeded
    if (cache->size > cache->capacity) {

        Node *lru = cache->tail->prev;

        removeNode(cache, lru);
        hashDelete(cache, lru->key);

        free(lru);

        cache->size--;
    }
}


// Display cache
void display(LRUCache *cache) {

    Node *current = cache->head->next;

    printf("Cache: ");

    while (current != cache->tail) {
        printf("[%d:%d] ", current->key, current->value);
        current = current->next;
    }

    printf("\n");
}


// Main function
int main() {

    LRUCache *cache = createCache(2);

    put(cache, 1, 10);
    put(cache, 2, 20);

    display(cache);

    printf("Get 1: %d\n", get(cache, 1));

    display(cache);

    put(cache, 3, 30);

    display(cache);

    printf("Get 2: %d\n", get(cache, 2));

    printf("Get 3: %d\n", get(cache, 3));

    display(cache);

    return 0;
}

